<div class="phone">
  <header>
    <button class="back-arrow">←</button>
    <h1>الدفة</h1>
  </header>
  <ul class="cart-items">
    <li class="item" data-price="10">
      <div class="photo-placeholder"></div>
      <div class="details">
        <span class="name">تفاحة</span>
        <div class="stepper">
          <button class="dec">-</button>
          <input type="number" value="1" min="0">
          <button class="inc">+</button>
        </div>
        <span class="price">10 AED</span>
      </div>
    </li>
    <li class="item" data-price="15">
      <div class="photo-placeholder"></div>
      <div class="details">
        <span class="name">حليب</span>
        <div class="stepper">
          <button class="dec">-</button>
          <input type="number" value="2" min="0">
          <button class="inc">+</button>
        </div>
        <span class="price">15 AED</span>
      </div>
    </li>
    <li class="item" data-price="8">
      <div class="photo-placeholder"></div>
      <div class="details">
        <span class="name">برتقال</span>
        <div class="stepper">
          <button class="dec">-</button>
          <input type="number" value="3" min="0">
          <button class="inc">+</button>
        </div>
        <span class="price">8 AED</span>
      </div>
    </li>
  </ul>
  <div class="promo-field">
    <input type="text" placeholder="كود الخصم">
  </div>
  <div class="summary">
    <div class="row">
      <span>المجموع الفرعي</span>
      <span id="subtotal">0 AED</span>
    </div>
    <div class="row">
      <span>توصيل</span>
      <span id="delivery">10 AED</span>
    </div>
    <div class="row">
      <span>ضريبة 5%</span>
      <span id="vat">0 AED</span>
    </div>
    <div class="row total">
      <span>الإجمالي</span>
      <span id="total">0 AED</span>
    </div>
  </div>
  <button class="place-order">إتمام الطلب</button>
</div>
<script>
  const items = document.querySelectorAll('.item');
  const subtotalEl = document.getElementById('subtotal');
  const deliveryEl = document.getElementById('delivery');
  const vatEl = document.getElementById('vat');
  const totalEl = document.getElementById('total');
  const deliveryFee = 10; // AED

  function updateSummary() {
    let subtotal = 0;
    items.forEach(item => {
      const price = parseFloat(item.dataset.price);
      const qty = parseInt(item.querySelector('input').value, 10) || 0;
      subtotal += price * qty;
    });
    const vat = subtotal * 0.05;
    const total = subtotal + deliveryFee + vat;
    subtotalEl.textContent = subtotal.toFixed(2) + ' AED';
    vatEl.textContent = vat.toFixed(2) + ' AED';
    totalEl.textContent = total.toFixed(2) + ' AED';
  }

  items.forEach(item => {
    const incBtn = item.querySelector('.inc');
    const decBtn = item.querySelector('.dec');
    const input = item.querySelector('input');
    incBtn.addEventListener('click', () => {
      input.value = parseInt(input.value, 10) + 1;
      updateSummary();
    });
    decBtn.addEventListener('click', () => {
      let val = parseInt(input.value, 10) - 1;
      if (val < 0) val = 0;
      input.value = val;
      updateSummary();
    });
    input.addEventListener('change', updateSummary);
  });

  // initial calculation
  updateSummary();
</script>
</body>
